import type { SfxName } from "@video/presets";
import { publicUrl, sfxKey } from "@/providers/storage/paths";

// Sound effects for videos, kept in our storage (shared/sfx/, put there by scripts/setup/sfx.ts).
// whoosh, swish (whip), click and shutter are Remotion's CC0 sounds; pop, ding and rise are
// generated by our own code, so every sound is free to use in client ads.

export const SFX_NAMES: SfxName[] = ["whoosh", "swish", "pop", "ding", "click", "shutter", "rise"];

/** Links to every sound effect, for the timeline. */
export function sfxUrls(): Record<SfxName, string> {
  return Object.fromEntries(SFX_NAMES.map((name) => [name, publicUrl(sfxKey(name))])) as Record<SfxName, string>;
}
